node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update item status to returned with refund details
db.prepare(\`
  UPDATE order_items 
  SET item_status = 'return_requested',
      refund_amount = 88,
      refund_method = 'cc_21e6eed2'
  WHERE oi_id = 'ITEM-E5801A' AND order_id = 'ORD-E0E671'
\`).run();

// Verify the update
const item = db.prepare(\"SELECT oi_id, name, item_status, refund_amount, refund_method FROM order_items WHERE oi_id = 'ITEM-E5801A'\").get();
console.log('Updated item:', JSON.stringify(item, null, 2));

// Check the other item is unaffected
const other = db.prepare(\"SELECT oi_id, name, item_status FROM order_items WHERE oi_id = 'ITEM-9E0BB3'\").get();
console.log('Other item (unchanged):', JSON.stringify(other, null, 2));
"

